set role service_role;
select th.assert((select outcome from public.th_c28_outcome where who = 'holder') = 'evaluated at ' || (select v from public.th_c28_state) and (select outcome from public.th_c28_outcome where who = 'contender') = 'removed', 'both committed');
select th.assert((select input_version > (select v from public.th_c28_state) from public.card_payment_eval_versions where user_id = '00000000-0000-0000-0000-0000000000aa'),
  'the removal advanced the input version past the one the standalone evaluation published');
select th.assert((public.get_card_payment_states('00000000-0000-0000-0000-0000000000aa')->>'fresh')::boolean and (select evaluated_version = input_version from public.card_payment_eval_versions where user_id = '00000000-0000-0000-0000-0000000000aa'), 'and published its own final version: fresh, not the earlier evaluation''s states');
select th.assert((select coalesce(array_agg(a_plaid_transaction_id order by a_plaid_transaction_id), '{}') from public.card_payment_decisions where kind = 'destination_removed_card' and superseded_by is null) = array['c28-q'] and (select (l->>'state') || '/' || (l->>'reason') || '/' || coalesce(l->>'effectCents', 'null') from (select l from jsonb_array_elements(public.get_card_payment_states('00000000-0000-0000-0000-0000000000aa')->'legs') l where (l->>'transactionId')::uuid = (select id from public.transactions where plaid_transaction_id = 'c28-q')) x(l)) = 'untracked/removed_card/-6000', 'with the destination preserved');
